import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.C8822HRV.js";const u=JSON.parse('{"title":"What you can achieve with sdd","description":"Practical outcomes with sdd — paper trail per change, new product plan, AI handoffs in git, light or heavy process on one CLI.","frontmatter":{"title":"What you can achieve with sdd","description":"Practical outcomes with sdd — paper trail per change, new product plan, AI handoffs in git, light or heavy process on one CLI.","head":[["meta",{"property":"og:title","content":"What you can achieve with sdd · sdd"}],["meta",{"property":"og:description","content":"Practical outcomes with sdd — paper trail per change, new product plan, AI handoffs in git, light or heavy process on one CLI."}],["meta",{"property":"og:url","content":"https://harsha09.github.io/spec-driven-development/concepts/what-you-can-achieve/"}],["meta",{"property":"og:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["meta",{"name":"twitter:title","content":"What you can achieve with sdd · sdd"}],["meta",{"name":"twitter:description","content":"Practical outcomes with sdd — paper trail per change, new product plan, AI handoffs in git, light or heavy process on one CLI."}],["meta",{"name":"twitter:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["link",{"rel":"canonical","href":"https://harsha09.github.io/spec-driven-development/concepts/what-you-can-achieve/"}]]},"headers":[],"relativePath":"concepts/what-you-can-achieve.md","filePath":"concepts/what-you-can-achieve.md","lastUpdated":1785895617000}'),d={name:"concepts/what-you-can-achieve.md"};function i(n,t,s,c,h,l){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="what-you-can-achieve-with-sdd" tabindex="-1">What you can achieve with sdd <a class="header-anchor" href="#what-you-can-achieve-with-sdd" aria-label="Permalink to &quot;What you can achieve with sdd&quot;">​</a></h1><p>Not a feature list — <strong>things you’ll notice in the repo</strong> after a week.</p><h2 id="outcomes" tabindex="-1">Outcomes <a class="header-anchor" href="#outcomes" aria-label="Permalink to &quot;Outcomes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>How sdd helps</th></tr></thead><tbody><tr><td><strong>Leave a paper trail</strong></td><td>Each task gets a short folder: intent, design, tasks, verify notes</td></tr><tr><td><strong>Start a new product</strong></td><td>One idea → vision, requirements, feature list, architecture in <code>memory/</code></td></tr><tr><td><strong>Use AI without losing decisions</strong></td><td>The AI reads the same notes you commit</td></tr><tr><td><strong>Match process to risk</strong></td><td>Tiny fix stays short; big work can go deeper</td></tr><tr><td><strong>Stay local</strong></td><td>No cloud account for the process tool</td></tr><tr><td><strong>Share process with the team</strong></td><td>Workflows are files in git you can change</td></tr></tbody></table><h2 id="day-to-day-moves" tabindex="-1">Day-to-day moves <a class="header-anchor" href="#day-to-day-moves" aria-label="Permalink to &quot;Day-to-day moves&quot;">​</a></h2><ul><li>Start work: <code>sdd new &quot;…&quot;</code> (free-form) or <code>sdd backlog start F-001</code> (after greenfield)</li><li>New product: <code>sdd greenfield &quot;…&quot;</code> → complete → backlog</li><li>Move on: fill a short file → <code>sdd next</code></li><li>Check setup: <code>sdd doctor</code></li><li>Finish: <code>sdd verify</code> → <code>sdd complete</code></li><li>Switch work: <code>sdd checkout &lt;id&gt;</code></li></ul><h2 id="by-team-size" tabindex="-1">By team size <a class="header-anchor" href="#by-team-size" aria-label="Permalink to &quot;By team size&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Context</th><th>Typical use</th></tr></thead><tbody><tr><td><strong>Solo / small</strong></td><td>Hotfix and features; optional greenfield for a personal MVP</td></tr><tr><td><strong>Product team</strong></td><td>Greenfield once for the product spine; then shared feature packs</td></tr><tr><td><strong>Enterprise</strong></td><td>Longer path with hard gates when you need them</td></tr></tbody></table><p>Same CLI — different paths.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../tutorials/first-change">Start in 10 minutes</a></li><li><a href="./../guides/greenfield">New product</a></li><li><a href="./../guides/simple-feature">Simple feature</a></li><li><a href="./../guides/enterprise">Enterprise</a></li></ul>',11)])])}const g=e(d,[["render",i]]);export{u as __pageData,g as default};
